{
  "name": "广播UDP RPC端口映射客户端",
  "name_en": "Broadcast UDP RPC Port Mapper Client",
  "manufacturer": "",
  "description": "用于通过 UDP 广播查询和使用 ONC/Sun RPC 端口映射服务的网络客户端组件。它可在局域网内发现提供 RPC 服务的主机与端口，并可进行端口映射查询、注册、注销和转发调用，适合实验室自动化系统定位网络化仪器服务或其他 RPC 服务端点。",
  "description_en": "A network client component for querying and using the ONC/Sun RPC port-mapper service via UDP broadcast. It can discover hosts and ports that provide RPC services on a local network, and supports port-mapping lookup, registration, unregistration, and forwarded calls, which is useful in laboratory automation for locating networked instrument services or other RPC service endpoints.",
  "tag_hints": [
    "ONC RPC",
    "port mapper",
    "UDP broadcast",
    "network service discovery",
    "Sun RPC",
    "remote procedure call",
    "instrument network integration"
  ],
  "actions": [
    {
      "action_name": "auto-pack_auth",
      "description": "打包 RPC 认证信息。",
      "description_en": "Pack RPC authentication data."
    },
    {
      "action_name": "auto-pack_auth_unix",
      "description": "打包 UNIX 风格的 RPC 认证信息。",
      "description_en": "Pack UNIX-style RPC authentication data."
    },
    {
      "action_name": "auto-pack_callheader",
      "description": "打包 RPC 调用头。",
      "description_en": "Pack an RPC call header."
    },
    {
      "action_name": "auto-pack_replyheader",
      "description": "打包 RPC 应答头。",
      "description_en": "Pack an RPC reply header."
    },
    {
      "action_name": "auto-unpack_auth",
      "description": "解包 RPC 认证信息。",
      "description_en": "Unpack RPC authentication data."
    },
    {
      "action_name": "auto-unpack_callheader",
      "description": "解包 RPC 调用头。",
      "description_en": "Unpack an RPC call header."
    },
    {
      "action_name": "auto-unpack_replyheader",
      "description": "解包 RPC 应答头。",
      "description_en": "Unpack an RPC reply header."
    },
    {
      "action_name": "auto-make_call",
      "description": "构建并发起一次 RPC 调用。",
      "description_en": "Build and initiate an RPC call."
    },
    {
      "action_name": "auto-start_call",
      "description": "开始构建一次 RPC 调用。",
      "description_en": "Start building an RPC call."
    },
    {
      "action_name": "auto-do_call",
      "description": "执行 RPC 调用并处理结果。",
      "description_en": "Execute an RPC call and process the result."
    },
    {
      "action_name": "auto-mkcred",
      "description": "创建 RPC 凭证。",
      "description_en": "Create RPC credentials."
    },
    {
      "action_name": "auto-mkverf",
      "description": "创建 RPC 验证器。",
      "description_en": "Create an RPC verifier."
    },
    {
      "action_name": "auto-call_0",
      "description": "调用过程 0（通常用于连通性或基础探测）。",
      "description_en": "Call procedure 0, typically used for connectivity or basic probing."
    },
    {
      "action_name": "auto-set_reply_handler",
      "description": "设置应答处理器。",
      "description_en": "Set the reply handler."
    },
    {
      "action_name": "auto-set_timeout",
      "description": "设置网络超时时间。",
      "description_en": "Set the network timeout."
    },
    {
      "action_name": "auto-pack_mapping",
      "description": "打包端口映射条目。",
      "description_en": "Pack a port-mapping entry."
    },
    {
      "action_name": "auto-pack_pmaplist",
      "description": "打包端口映射列表。",
      "description_en": "Pack a port-mapper list."
    },
    {
      "action_name": "auto-pack_call_args",
      "description": "打包转发调用所需参数。",
      "description_en": "Pack arguments for a forwarded call."
    },
    {
      "action_name": "auto-unpack_mapping",
      "description": "解包端口映射条目。",
      "description_en": "Unpack a port-mapping entry."
    },
    {
      "action_name": "auto-unpack_pmaplist",
      "description": "解包端口映射列表。",
      "description_en": "Unpack a port-mapper list."
    },
    {
      "action_name": "auto-unpack_call_result",
      "description": "解包 RPC 调用结果。",
      "description_en": "Unpack an RPC call result."
    },
    {
      "action_name": "auto-set",
      "description": "设置或注册端口映射。",
      "description_en": "Set or register a port mapping."
    },
    {
      "action_name": "auto-unset",
      "description": "取消端口映射。",
      "description_en": "Unset a port mapping."
    },
    {
      "action_name": "auto-get_port",
      "description": "获取指定 RPC 程序对应的端口。",
      "description_en": "Get the port for a specified RPC program."
    },
    {
      "action_name": "auto-dump",
      "description": "列出当前端口映射表。",
      "description_en": "Dump the current port-mapping table."
    },
    {
      "action_name": "auto-callit",
      "description": "通过端口映射服务转发一次 RPC 调用。",
      "description_en": "Forward an RPC call through the port-mapper service."
    },
    {
      "action_name": "auto-my_reply_handler",
      "description": "处理当前客户端收到的应答。",
      "description_en": "Handle a reply received by this client."
    },
    {
      "action_name": "auto-register",
      "description": "注册 RPC 服务或程序。",
      "description_en": "Register an RPC service or program."
    },
    {
      "action_name": "auto-unregister",
      "description": "注销 RPC 服务或程序。",
      "description_en": "Unregister an RPC service or program."
    },
    {
      "action_name": "auto-handle",
      "description": "处理一次 RPC 请求或消息。",
      "description_en": "Handle an RPC request or message."
    },
    {
      "action_name": "auto-turn_around",
      "description": "将接收到的请求转换为应答处理流程。",
      "description_en": "Turn a received request around into a reply-handling flow."
    },
    {
      "action_name": "auto-handle_0",
      "description": "处理过程 0 请求。",
      "description_en": "Handle procedure 0 requests."
    },
    {
      "action_name": "auto-addpackers",
      "description": "添加协议打包器和解包器。",
      "description_en": "Add protocol packers and unpackers."
    },
    {
      "action_name": "auto-loop",
      "description": "进入持续监听与处理循环。",
      "description_en": "Enter the continuous listen-and-handle loop."
    },
    {
      "action_name": "auto-session",
      "description": "处理一次会话。",
      "description_en": "Process a single session."
    },
    {
      "action_name": "auto-forkingloop",
      "description": "以分叉子进程方式循环处理请求。",
      "description_en": "Process requests in a loop using forked child processes."
    },
    {
      "action_name": "auto-forksession",
      "description": "以子进程方式处理单次会话。",
      "description_en": "Process a single session in a child process."
    }
  ]
}

